	-- 2)
CREATE TEMPORARY TABLE InvBatch (
DateKey INT, 
SKU VARCHAR(60), 
FactoryCode VARCHAR(30),
OnHandQty DECIMAL(18,2), 
AvailableQty DECIMAL(18,2), 
ReservedQty DECIMAL(18,2), 
InTransitQty DECIMAL(18,2), 
InventoryValue DECIMAL(18,2)
);




SELECT ib.DateKey, p.ProductKey, f.FactoryKey, ib.OnHandQty, ib.AvailableQty, ib.ReservedQty, ib.InTransitQty, ib.InventoryValue
FROM InvBatch ib
JOIN DimProduct p ON p.SKU = ib.SKU
JOIN DimFactory f ON f.FactoryCode = ib.FactoryCode;


SELECT * FROM FactInventory;

SELECT COUNT(*) AS TotalInventory
FROM FactInventory;

SELECT 
    MIN(DateKey) AS MinimumDateKey,
    MAX(DateKey) AS MaximumDateKey
FROM FactInventory;

DROP TEMPORARY TABLE IF EXISTS InvBatch;